import { createHmac, randomBytes, timingSafeEqual } from 'crypto';
import type { CookieOptions } from 'express';

export const OAUTH_STATE_COOKIE = 'oauth_state';
/** The cookie only travels to the Google endpoints (it includes /callback by prefix). */
export const OAUTH_STATE_COOKIE_PATH = '/api/auth/google';
export const OAUTH_STATE_TTL_MS = 10 * 60 * 1000;

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace -- required syntax for augmenting Express's global namespace
  namespace Express {
    interface Request {
      /** Nonce `state` generated by the start guard and passed to Passport. */
      oauthState?: string;
      /** Index (in the FRONTEND_URL whitelist) of the origin to return to after the login. */
      oauthRedirectIndex?: number;
    }
  }
}

const sign = (secret: string, payload: string): string =>
  createHmac('sha256', secret)
    .update(`oauth-state:${payload}`)
    .digest('base64url');

const safeEqual = (a: string, b: string): boolean => {
  const left = Buffer.from(a);
  const right = Buffer.from(b);
  return left.length === right.length && timingSafeEqual(left, right);
};

/**
 * Generates the anti-CSRF `state`: a random nonce that travels in the URL to Google and,
 * signed with HMAC, in an httpOnly cookie of the browser that started the flow.
 * On return the two must match: a callback prepared by another browser
 * (or forged) does not have the right cookie. `redirectIndex` is signed together with the nonce,
 * so it cannot be altered to hijack the final redirect.
 */
export function createOAuthState(
  secret: string,
  redirectIndex = 0,
): { state: string; cookie: string } {
  const nonce = randomBytes(32).toString('base64url');
  const payload = `${nonce}.${redirectIndex}`;
  return { state: nonce, cookie: `${payload}.${sign(secret, payload)}` };
}

/** Verifies the cookie + the callback's `state` parameter. Returns null if they do not match or the signature is not valid. */
export function verifyOAuthState(
  secret: string,
  cookie: unknown,
  state: unknown,
): { redirectIndex: number } | null {
  if (typeof cookie !== 'string' || typeof state !== 'string' || !state) {
    return null;
  }
  const parts = cookie.split('.');
  if (parts.length !== 3) return null;
  const [nonce, index, signature] = parts;
  if (!/^\d{1,3}$/.test(index)) return null;
  if (!safeEqual(signature, sign(secret, `${nonce}.${index}`))) return null;
  if (!safeEqual(nonce, state)) return null;
  return { redirectIndex: Number(index) };
}

export function oauthStateCookieOptions(isProduction: boolean): CookieOptions {
  return {
    httpOnly: true,
    secure: isProduction,
    // Lax: the return from Google is a top-level GET navigation, the cookie must arrive.
    sameSite: 'lax',
    path: OAUTH_STATE_COOKIE_PATH,
    maxAge: OAUTH_STATE_TTL_MS,
  };
}
